fn xs_next(mut x: u64) -> u64 { x ^= x << 13; x ^= x >> 7; x ^= x << 17; x }
fn main(){ let w: usize=256; let mut a: Vec<u8>=vec![0; w*w]; let mut b: Vec<u8>=vec![0; w*w]; let mut r:u64=12345; for i in 0..w*w { r=xs_next(r); a[i]=(r%256) as u8; } let blur=|s:&Vec<u8>,d:&mut Vec<u8>|{ for y in 1..w-1 { for x in 1..w-1 { let i=y*w+x; let sm = s[i-w-1] as u32 + s[i-w] as u32*2 + s[i-w+1] as u32 + s[i-1] as u32*2 + s[i] as u32*4 + s[i+1] as u32*2 + s[i+w-1] as u32 + s[i+w] as u32*2 + s[i+w+1] as u32; d[i]=(sm>>4) as u8; } } }; for _ in 0..8 { blur(&a,&mut b); blur(&b,&mut a); } let total: usize = a.iter().map(|&v| v as usize).sum(); println!("{}",w); println!("{}",total); }